BEGIN;

CREATE SCHEMA ministry_private;

REVOKE ALL ON SCHEMA ministry_private FROM PUBLIC, anon, authenticated;

SET LOCAL search_path = ministry_private, pg_catalog;

CREATE TABLE "announcements" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY,
  "title" varchar(200) NOT NULL,
  "message" text NOT NULL,
  "announcement_date" date DEFAULT NULL,
  "priority" text NOT NULL DEFAULT 'Normal' CHECK ("priority" IN ('Low','Normal','High','Urgent')),
  "status" text NOT NULL DEFAULT 'Published' CHECK ("status" IN ('Draft','Published')),
  "target_audience" text DEFAULT NULL CHECK ("target_audience" IN ('All','Members','Leaders','Department','Visitors')),
  "target_department_id" int DEFAULT NULL,
  "posted_by" int DEFAULT NULL,
  "created_at" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);

CREATE TABLE "attendance_records" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY,
  "session_id" int NOT NULL,
  "member_id" int NOT NULL,
  "status" text DEFAULT 'Present' CHECK ("status" IN ('Present','Absent')),
  "marked_at" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  "remarks" text,
  PRIMARY KEY ("id"),
  UNIQUE ("session_id","member_id")
);

CREATE TABLE "attendance_sessions" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY,
  "session_date" date NOT NULL,
  "service_type" text NOT NULL CHECK ("service_type" IN ('Sabbath Service','Sabbath School','Midweek Service','Vespers','Department Meeting','Special Program','Other')),
  "department_id" int DEFAULT NULL,
  "notes" text,
  "created_by" int DEFAULT NULL,
  "created_at" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);

CREATE TABLE "care_followups" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY,
  "member_id" int NOT NULL,
  "followup_type" varchar(100) DEFAULT NULL,
  "followup_date" date DEFAULT NULL,
  "next_followup_date" date DEFAULT NULL,
  "notes" text,
  "reason" text NOT NULL CHECK ("reason" IN ('Missed Services','Sick Member','Visitation','New Convert','Prayer Request','Bereavement','Counselling','Other')),
  "description" text,
  "assigned_to" int DEFAULT NULL,
  "status" text DEFAULT 'Pending' CHECK ("status" IN ('Pending','In Progress','Completed')),
  "due_date" date DEFAULT NULL,
  "created_by" int DEFAULT NULL,
  "created_at" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);

CREATE TABLE "church_profile" (
  "id" int NOT NULL,
  "church_name" varchar(180) NOT NULL DEFAULT '',
  "denomination" varchar(180) DEFAULT '',
  "address" varchar(255) DEFAULT '',
  "city" varchar(120) DEFAULT '',
  "province" varchar(120) DEFAULT '',
  "phone" varchar(60) DEFAULT '',
  "email" varchar(180) DEFAULT '',
  "website" varchar(255) DEFAULT '',
  "pastor_name" varchar(180) DEFAULT '',
  "service_times" text,
  "mission_statement" text,
  "updated_by" int DEFAULT NULL,
  "updated_at" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  "district" varchar(150) DEFAULT NULL,
  "conference" varchar(150) DEFAULT NULL,
  "pastor_phone" varchar(30) DEFAULT NULL,
  "first_elder_name" varchar(150) DEFAULT NULL,
  "first_elder_phone" varchar(30) DEFAULT NULL,
  "clerk_name" varchar(150) DEFAULT NULL,
  "clerk_phone" varchar(30) DEFAULT NULL,
  "treasurer_name" varchar(150) DEFAULT NULL,
  "treasurer_phone" varchar(30) DEFAULT NULL,
  PRIMARY KEY ("id")
);

CREATE TABLE "contributions" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY,
  "member_id" int DEFAULT NULL,
  "contribution_category" text NOT NULL CHECK ("contribution_category" IN ('Tithe','Offering','Special Offering','Donation','Building Fund','Welfare','Camp Meeting','Dorcas','Youth Fund','Other')),
  "amount" decimal(10,2) NOT NULL,
  "contribution_date" date NOT NULL,
  "payment_method" text DEFAULT NULL CHECK ("payment_method" IN ('Cash','Mobile Money','Bank Transfer','Cheque','Other')),
  "recorded_by" int DEFAULT NULL,
  "notes" text,
  "created_at" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);

CREATE TABLE "departments" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY,
  "name" varchar(100) NOT NULL,
  "description" text,
  "created_at" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  UNIQUE ("name")
);

CREATE TABLE "events" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY,
  "title" varchar(200) NOT NULL,
  "description" text,
  "event_type" text DEFAULT 'Other' CHECK ("event_type" IN ('Sabbath Program','Midweek Service','Vespers','Seminar','Baptism','Department Meeting','Other')),
  "event_date" date NOT NULL,
  "event_time" time DEFAULT NULL,
  "end_time" time DEFAULT NULL,
  "location" varchar(200) DEFAULT NULL,
  "department_id" int DEFAULT NULL,
  "created_by" int DEFAULT NULL,
  "created_at" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);

CREATE TABLE "member_departments" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY,
  "member_id" int NOT NULL,
  "department_id" int NOT NULL,
  "role_in_department" varchar(100) DEFAULT 'Member',
  "created_at" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  UNIQUE ("member_id","department_id")
);

CREATE TABLE "members" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY,
  "first_name" varchar(50) NOT NULL,
  "last_name" varchar(50) NOT NULL,
  "gender" text NOT NULL CHECK ("gender" IN ('Male','Female')),
  "date_of_birth" date DEFAULT NULL,
  "phone" varchar(20) DEFAULT NULL,
  "email" varchar(100) DEFAULT NULL,
  "address" text,
  "baptism_status" text DEFAULT 'Unknown' CHECK ("baptism_status" IN ('Baptized','Not Baptized','Unknown')),
  "baptism_date" date DEFAULT NULL,
  "membership_status" text DEFAULT 'Active' CHECK ("membership_status" IN ('Active','Inactive','Transferred','Deceased')),
  "follow_up_status" text DEFAULT 'Okay' CHECK ("follow_up_status" IN ('Okay','Needs Follow-Up')),
  "created_at" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  "marital_status" text DEFAULT 'Single' CHECK ("marital_status" IN ('Single','Married','Divorced','Widowed')),
  "spouse_name" varchar(100) DEFAULT NULL,
  "number_of_children" int DEFAULT '0',
  "children_details" text,
  "occupation" varchar(100) DEFAULT NULL,
  "employer" varchar(150) DEFAULT NULL,
  "ministry_role" varchar(100) DEFAULT NULL,
  "date_joined_church" date DEFAULT NULL,
  PRIMARY KEY ("id")
);

CREATE TABLE "program_items" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY,
  "event_id" int NOT NULL,
  "item_order" int NOT NULL,
  "item_title" varchar(150) NOT NULL,
  "assigned_to" varchar(100) DEFAULT NULL,
  "start_time" time DEFAULT NULL,
  "notes" text,
  "created_at" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);

CREATE TABLE "tasks" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY,
  "title" varchar(200) NOT NULL,
  "description" text,
  "assigned_to" int DEFAULT NULL,
  "department_id" int DEFAULT NULL,
  "related_member_id" int DEFAULT NULL,
  "status" text DEFAULT 'Pending' CHECK ("status" IN ('Pending','In Progress','Completed')),
  "due_date" date DEFAULT NULL,
  "created_by" int DEFAULT NULL,
  "created_at" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);

CREATE TABLE "users" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY,
  "full_name" varchar(100) NOT NULL,
  "email" varchar(100) NOT NULL,
  "password" varchar(255) NOT NULL,
  "role" text DEFAULT 'leader' CHECK ("role" IN ('admin','leader','treasurer')),
  "created_at" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  "status" text NOT NULL DEFAULT 'Active' CHECK ("status" IN ('Active','Inactive')),
  PRIMARY KEY ("id"),
  UNIQUE ("email")
);

CREATE TABLE "visitor_followups" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY,
  "visitor_id" int NOT NULL,
  "follow_up_date" date NOT NULL,
  "follow_up_method" text DEFAULT 'Call' CHECK ("follow_up_method" IN ('Call','SMS','WhatsApp','Visit','In Person','Other')),
  "notes" text,
  "handled_by" int DEFAULT NULL,
  "created_at" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);

CREATE TABLE "visitors" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY,
  "first_name" varchar(50) NOT NULL,
  "last_name" varchar(50) NOT NULL,
  "gender" text DEFAULT NULL CHECK ("gender" IN ('Male','Female')),
  "phone" varchar(20) DEFAULT NULL,
  "email" varchar(100) DEFAULT NULL,
  "visit_date" date NOT NULL,
  "invited_by" varchar(100) DEFAULT NULL,
  "interested_in_bible_study" text DEFAULT 'Unknown' CHECK ("interested_in_bible_study" IN ('Yes','No','Unknown')),
  "wants_follow_up" text DEFAULT 'Yes' CHECK ("wants_follow_up" IN ('Yes','No')),
  "follow_up_status" text DEFAULT 'New Visitor' CHECK ("follow_up_status" IN ('New Visitor','Contacted','Invited Again','Joined Class','Baptized','Became Member')),
  "converted_member_id" int DEFAULT NULL,
  "notes" text,
  "created_at" timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  "address" varchar(255) DEFAULT NULL,
  PRIMARY KEY ("id")
);

ALTER TABLE "announcements" ADD CONSTRAINT "announcements_ibfk_1" FOREIGN KEY ("target_department_id") REFERENCES "departments" ("id") ON DELETE SET NULL;

ALTER TABLE "announcements" ADD CONSTRAINT "announcements_ibfk_2" FOREIGN KEY ("posted_by") REFERENCES "users" ("id") ON DELETE SET NULL;

ALTER TABLE "attendance_records" ADD CONSTRAINT "attendance_records_ibfk_1" FOREIGN KEY ("session_id") REFERENCES "attendance_sessions" ("id") ON DELETE CASCADE;

ALTER TABLE "attendance_records" ADD CONSTRAINT "attendance_records_ibfk_2" FOREIGN KEY ("member_id") REFERENCES "members" ("id") ON DELETE CASCADE;

ALTER TABLE "attendance_sessions" ADD CONSTRAINT "attendance_sessions_ibfk_1" FOREIGN KEY ("department_id") REFERENCES "departments" ("id") ON DELETE SET NULL;

ALTER TABLE "attendance_sessions" ADD CONSTRAINT "attendance_sessions_ibfk_2" FOREIGN KEY ("created_by") REFERENCES "users" ("id") ON DELETE SET NULL;

ALTER TABLE "care_followups" ADD CONSTRAINT "care_followups_ibfk_1" FOREIGN KEY ("member_id") REFERENCES "members" ("id") ON DELETE CASCADE;

ALTER TABLE "care_followups" ADD CONSTRAINT "care_followups_ibfk_2" FOREIGN KEY ("assigned_to") REFERENCES "users" ("id") ON DELETE SET NULL;

ALTER TABLE "care_followups" ADD CONSTRAINT "care_followups_ibfk_3" FOREIGN KEY ("created_by") REFERENCES "users" ("id") ON DELETE SET NULL;

ALTER TABLE "contributions" ADD CONSTRAINT "contributions_ibfk_1" FOREIGN KEY ("member_id") REFERENCES "members" ("id") ON DELETE SET NULL;

ALTER TABLE "contributions" ADD CONSTRAINT "contributions_ibfk_2" FOREIGN KEY ("recorded_by") REFERENCES "users" ("id") ON DELETE SET NULL;

ALTER TABLE "events" ADD CONSTRAINT "events_ibfk_1" FOREIGN KEY ("department_id") REFERENCES "departments" ("id") ON DELETE SET NULL;

ALTER TABLE "events" ADD CONSTRAINT "events_ibfk_2" FOREIGN KEY ("created_by") REFERENCES "users" ("id") ON DELETE SET NULL;

ALTER TABLE "member_departments" ADD CONSTRAINT "member_departments_ibfk_1" FOREIGN KEY ("member_id") REFERENCES "members" ("id") ON DELETE CASCADE;

ALTER TABLE "member_departments" ADD CONSTRAINT "member_departments_ibfk_2" FOREIGN KEY ("department_id") REFERENCES "departments" ("id") ON DELETE CASCADE;

ALTER TABLE "program_items" ADD CONSTRAINT "program_items_ibfk_1" FOREIGN KEY ("event_id") REFERENCES "events" ("id") ON DELETE CASCADE;

ALTER TABLE "tasks" ADD CONSTRAINT "tasks_ibfk_1" FOREIGN KEY ("assigned_to") REFERENCES "users" ("id") ON DELETE SET NULL;

ALTER TABLE "tasks" ADD CONSTRAINT "tasks_ibfk_2" FOREIGN KEY ("department_id") REFERENCES "departments" ("id") ON DELETE SET NULL;

ALTER TABLE "tasks" ADD CONSTRAINT "tasks_ibfk_3" FOREIGN KEY ("related_member_id") REFERENCES "members" ("id") ON DELETE SET NULL;

ALTER TABLE "tasks" ADD CONSTRAINT "tasks_ibfk_4" FOREIGN KEY ("created_by") REFERENCES "users" ("id") ON DELETE SET NULL;

ALTER TABLE "visitor_followups" ADD CONSTRAINT "visitor_followups_ibfk_1" FOREIGN KEY ("visitor_id") REFERENCES "visitors" ("id") ON DELETE CASCADE;

ALTER TABLE "visitor_followups" ADD CONSTRAINT "visitor_followups_ibfk_2" FOREIGN KEY ("handled_by") REFERENCES "users" ("id") ON DELETE SET NULL;

ALTER TABLE "visitors" ADD CONSTRAINT "visitors_ibfk_1" FOREIGN KEY ("converted_member_id") REFERENCES "members" ("id") ON DELETE SET NULL;

CREATE INDEX "idx_announcements_target_department_id" ON "announcements" ("target_department_id");

CREATE INDEX "idx_announcements_posted_by" ON "announcements" ("posted_by");

CREATE INDEX "idx_attendance_records_member_id" ON "attendance_records" ("member_id");

CREATE INDEX "idx_attendance_sessions_department_id" ON "attendance_sessions" ("department_id");

CREATE INDEX "idx_attendance_sessions_created_by" ON "attendance_sessions" ("created_by");

CREATE INDEX "idx_care_followups_member_id" ON "care_followups" ("member_id");

CREATE INDEX "idx_care_followups_assigned_to" ON "care_followups" ("assigned_to");

CREATE INDEX "idx_care_followups_created_by" ON "care_followups" ("created_by");

CREATE INDEX "idx_contributions_member_id" ON "contributions" ("member_id");

CREATE INDEX "idx_contributions_recorded_by" ON "contributions" ("recorded_by");

CREATE INDEX "idx_events_department_id" ON "events" ("department_id");

CREATE INDEX "idx_events_created_by" ON "events" ("created_by");

CREATE INDEX "idx_member_departments_department_id" ON "member_departments" ("department_id");

CREATE INDEX "idx_program_items_event_id" ON "program_items" ("event_id");

CREATE INDEX "idx_tasks_assigned_to" ON "tasks" ("assigned_to");

CREATE INDEX "idx_tasks_department_id" ON "tasks" ("department_id");

CREATE INDEX "idx_tasks_related_member_id" ON "tasks" ("related_member_id");

CREATE INDEX "idx_tasks_created_by" ON "tasks" ("created_by");

CREATE INDEX "idx_visitor_followups_visitor_id" ON "visitor_followups" ("visitor_id");

CREATE INDEX "idx_visitor_followups_handled_by" ON "visitor_followups" ("handled_by");

CREATE INDEX "idx_visitors_converted_member_id" ON "visitors" ("converted_member_id");

ALTER TABLE "announcements" ENABLE ROW LEVEL SECURITY;

ALTER TABLE "attendance_records" ENABLE ROW LEVEL SECURITY;

ALTER TABLE "attendance_sessions" ENABLE ROW LEVEL SECURITY;

ALTER TABLE "care_followups" ENABLE ROW LEVEL SECURITY;

ALTER TABLE "church_profile" ENABLE ROW LEVEL SECURITY;

ALTER TABLE "contributions" ENABLE ROW LEVEL SECURITY;

ALTER TABLE "departments" ENABLE ROW LEVEL SECURITY;

ALTER TABLE "events" ENABLE ROW LEVEL SECURITY;

ALTER TABLE "member_departments" ENABLE ROW LEVEL SECURITY;

ALTER TABLE "members" ENABLE ROW LEVEL SECURITY;

ALTER TABLE "program_items" ENABLE ROW LEVEL SECURITY;

ALTER TABLE "tasks" ENABLE ROW LEVEL SECURITY;

ALTER TABLE "users" ENABLE ROW LEVEL SECURITY;

ALTER TABLE "visitor_followups" ENABLE ROW LEVEL SECURITY;

ALTER TABLE "visitors" ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON ALL TABLES IN SCHEMA ministry_private FROM PUBLIC, anon, authenticated;

REVOKE ALL ON ALL SEQUENCES IN SCHEMA ministry_private FROM PUBLIC, anon, authenticated;

COMMIT;
